  CompactLineageEdgeV1: {"additionalProperties":false,"properties":{"authority":{"type":"string"},"authorized":{"type":"boolean"},"kind":{"type":"string"},"knowledge_at":{"format":"int64","type":"integer"},"object_anchor_id":{"type":"string"},"subject_anchor_id":{"type":"string"},"supporting_anchor_ids":{"items":{"type":"string"},"type":"array"}},"required":["kind","subject_anchor_id","object_anchor_id","knowledge_at","authority","authorized","supporting_anchor_ids"],"type":"object"},
