  ConfigKeyFoundV1: {"additionalProperties":false,"properties":{"file":{"type":"string"},"key":{"type":"string"},"line":{"description":"The first line whose text starts with the key's leaf segment.","format":"uint32","minimum":0,"type":["integer","null"]},"value":true},"required":["file","key","value"],"type":"object"},
  ConfigKeyMissingV1: {"additionalProperties":false,"description":"`value` is always null and `found` always false; both stay on the wire\nso a missing key reads the same as it always has.","properties":{"file":{"type":"string"},"found":{"type":"boolean"},"key":{"type":"string"},"value":{"type":"null"}},"required":["file","key","value","found"],"type":"object"},
  ConfigMatchV1: {"anyOf":[{"$ref":"#/$defs/ConfigParseErrorV1"},{"$ref":"#/$defs/ConfigKeyMissingV1"},{"$ref":"#/$defs/ConfigKeyFoundV1"}],"description":"One queried config file: the file's parse error, the key's absence, or the\nkey's value and defining line.\n\nThe variants are distinguished by their exact field sets, so each one\ndenies unknown fields and the most specific shapes are tried first."},
