  ConfigurationCandidateV1: {"additionalProperties":false,"description":"Resolution provenance is intentionally distinct from behavior. Moving the\nsame winner between layers can change this material without changing the\neffective behavior digest.","properties":{"disposition":{"$ref":"#/$defs/CandidateDispositionV1"},"layer":{"$ref":"#/$defs/ConfigurationLayerIdV1"},"revision_id":{"$ref":"#/$defs/ConfigurationRevisionId"},"safe_reason":{"type":["string","null"]}},"required":["layer","revision_id","disposition"],"type":"object"},
