  ConfigurationIdempotencyKey: {"description":"Strongly typed canonical identity: `ConfigurationIdempotencyKey`.","type":"string"},
  ConfigurationLayerIdV1: {"description":"A typed configuration layer identity. The default layer intentionally has\nno caller-controlled identifier.","oneOf":[{"properties":{"kind":{"const":"default","type":"string"}},"required":["kind"],"type":"object"},{"properties":{"kind":{"const":"user_profile","type":"string"},"profile_id":{"$ref":"#/$defs/UserProfileId"}},"required":["kind","profile_id"],"type":"object"},{"properties":{"kind":{"const":"project","type":"string"},"project_id":{"$ref":"#/$defs/ProjectId"}},"required":["kind","project_id"],"type":"object"},{"properties":{"collection_id":{"$ref":"#/$defs/QueryCollectionId"},"kind":{"const":"collection","type":"string"}},"required":["kind","collection_id"],"type":"object"}]},
