  ConstructorsNotFoundV1: {"additionalProperties":false,"properties":{"found":{"description":"Always `false`: no struct, class, or case class has the name.","type":"boolean"},"freshness":{"anyOf":[{"$ref":"#/$defs/PrimitiveSearchFreshnessV1"},{"type":"null"}],"description":"The worktree verdict a served graph read opens with."},"match_count":{"format":"uint64","minimum":0,"type":"integer"},"message":{"type":"string"},"sites":{"items":{"$ref":"#/$defs/ConstructorSiteV1"},"type":"array"},"struct":{"type":"string"}},"required":["found","struct","message","match_count","sites"],"type":"object"},
  ConstructorsReportV1: {"additionalProperties":false,"properties":{"candidate_count":{"format":"uint64","minimum":0,"type":"integer"},"expected_fields":{"description":"`None` when the name resolves to more than one definition.","items":{"type":"string"},"type":["array","null"]},"freshness":{"anyOf":[{"$ref":"#/$defs/PrimitiveSearchFreshnessV1"},{"type":"null"}],"description":"The worktree verdict a served graph read opens with."},"match_count":{"format":"uint64","minimum":0,"type":"integer"},"resolution_reason":{"$ref":"#/$defs/ConstructorResolutionReasonV1"},"resolution_status":{"$ref":"#/$defs/ConstructorResolutionStatusV1"},"sites":{"items":{"$ref":"#/$defs/ConstructorSiteV1"},"type":"array"},"struct":{"type":"string"}},"required":["struct","candidate_count","resolution_status","resolution_reason","match_count","sites"],"type":"object"},
