  ContextExtensionPointV1: {"additionalProperties":false,"description":"A public trait or interface among the context's selected symbols.","properties":{"file":{"type":"string"},"implementor_count":{"format":"uint","minimum":0,"type":"integer"},"kind":{"type":"string"},"line":{"format":"uint32","minimum":0,"type":"integer"},"name":{"type":"string"}},"required":["name","kind","file","line","implementor_count"],"type":"object"},
  ContextLexicalAnchorV1: {"description":"What one caller `lexical_anchors` entry contributed to the response, in\ncaller order.","oneOf":[{"additionalProperties":false,"description":"`matched` indexed rows carried the anchor; `admitted` result sites\ncarrying it are in this response, and `dropped` counts the sites the\nlexical lane admitted that a later stage removed, by reason.","properties":{"admitted":{"format":"uint64","minimum":0,"type":"integer"},"anchor":{"type":"string"},"dropped":{"items":{"$ref":"#/$defs/LexicalAnchorDropV1"},"type":"array"},"matched":{"format":"uint64","minimum":0,"type":"integer"},"outcome":{"const":"matched","type":"string"}},"required":["outcome","anchor","matched","admitted"],"type":"object"},{"additionalProperties":false,"description":"No indexed row carries the anchor.","properties":{"anchor":{"type":"string"},"outcome":{"const":"unmatched","type":"string"}},"required":["outcome","anchor"],"type":"object"},{"additionalProperties":false,"description":"The anchor's route did not serve; `coverage` names the lane state.","properties":{"anchor":{"type":"string"},"outcome":{"const":"not_served","type":"string"}},"required":["outcome","anchor"],"type":"object"}]},
  ContextModeV1: {"enum":["explore","plan"],"type":"string"},
