  ContextRelatedOmissionV1: {"additionalProperties":false,"description":"Related symbols `context` ranked but did not return.","properties":{"omitted":{"description":"Ranked related symbols the `max_nodes` cut dropped.","format":"uint","minimum":0,"type":"integer"},"total":{"description":"Distinct related symbols the walk found and ranked.","format":"uint","minimum":0,"type":"integer"},"total_is_lower_bound":{"description":"The neighbor walk stopped at its row limit, so `total` is a lower\nbound.","type":"boolean"}},"required":["total","omitted","total_is_lower_bound"],"type":"object"},
  ContextRetrievalPlanV1: {"additionalProperties":false,"description":"The retrieval plan `context` executed: which stages ran, what each\nadmitted, and where a budget bounded the answer. Lane-level serving state\nstays in `coverage`.","properties":{"code":{"$ref":"#/$defs/ContextStageV1","description":"Source bodies for selected symbols, bounded by `max_code_blocks`."},"graph":{"$ref":"#/$defs/ContextStageV1","description":"Candidates resolved to verified graph symbols."},"memory":{"$ref":"#/$defs/ContextStageV1","description":"Project memory facts, bounded by `memory_limit`."},"related":{"$ref":"#/$defs/ContextStageV1","description":"Ranked neighbors of the selected symbols, bounded by `max_nodes`."},"search":{"$ref":"#/$defs/ContextStageV1","description":"Ranked code-index candidates, bounded by `max_nodes`."}},"required":["search","graph","related","code","memory"],"type":"object"},
  ContextScoutAddressV1: {"additionalProperties":false,"description":"Exact opaque destination for one public Context Scout operation.\n\nThe daemon converts this transport-neutral address into its runtime value\nonly after catalog admission. Keeping the public wire here makes CLI, MCP,\nHTTP, and both SDKs share one generated schema authority.","properties":{"agent_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"},"logical_message_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"},"profile_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"},"project_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"},"protected_session_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":32,"minItems":32,"type":"array"},"provider_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"},"thread_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"},"turn_id":{"items":{"format":"uint8","maximum":255,"minimum":0,"type":"integer"},"maxItems":16,"minItems":16,"type":"array"}},"required":["profile_id","provider_id","protected_session_id","thread_id","turn_id","agent_id","logical_message_id","project_id"],"type":"object"},
  ContextScoutCategoryV1: {"enum":["retrieval","diagnostic","coordination","verification"],"type":"string"},
