  LanguageServerAnalyzerStateV1: {"description":"State of one analyzer as the daemon owner holds it.\n\n`Inactive` is the one state the aggregate never takes: the language has no\nfiles in the project, so Doctor does not grade it, but `lsp servers` still\nlists it from this same read so both surfaces share one authority.","enum":["ready","available","refreshing","disabled","unavailable","crashed","inactive"],"type":"string"},
  LanguageServerAnalyzerV1: {"description":"Live state of one analyzer the daemon resolved for the current project.\n\n`LanguageServerStateV1` is the aggregate the finding is graded on; this is\nthe per-analyzer evidence behind it, so an operator learns *which*\nexecutable is missing and how to install it, resolved by the daemon\nprocess (the only PATH that matters, since the daemon spawns analyzers)\nrather than by whichever shell ran the CLI.","properties":{"command":{"description":"The configured executable, after any operator command override.","type":"string"},"detail":{"description":"The owner's last recorded error for this analyzer, when one exists.","type":["string","null"]},"executable_found":{"description":"Whether the daemon process finds `command` on its own PATH. For an\nactive analyzer `state` is the finer verdict (a rustup proxy whose\ntoolchain lacks the component is found yet `Unavailable`); for an\ninactive one this is the only availability evidence.","type":"boolean"},"install":{"description":"The first install command the adapter advertises, when one exists.","type":["string","null"]},"language":{"description":"Adapter language (`typescript`, `rust`, …).","type":"string"},"state":{"$ref":"#/$defs/LanguageServerAnalyzerStateV1"}},"required":["language","command","state","executable_found"],"type":"object"},
  LanguageServerReadV1: {"description":"One live read from the daemon language-server/analyzer owner.","oneOf":[{"description":"The owner observed all project-active analyzer states.","properties":{"analyzers":{"default":[],"description":"Every analyzer the owner resolved, active or not; the aggregate\n`state` covers the active ones only.","items":{"$ref":"#/$defs/LanguageServerAnalyzerV1"},"type":"array"},"coverage":{"$ref":"#/$defs/DoctorCoverageCompletenessV1"},"kind":{"const":"observed","type":"string"},"state":{"$ref":"#/$defs/LanguageServerStateV1"}},"required":["kind","state","coverage"],"type":"object"},{"description":"Language-server inspection is unsupported on this build/platform.","properties":{"kind":{"const":"unsupported","type":"string"}},"required":["kind"],"type":"object"},{"description":"No project-active analyzer is configured. The owner's inactive\nanalyzers are still carried so `lsp servers` can list them.","properties":{"analyzers":{"default":[],"items":{"$ref":"#/$defs/LanguageServerAnalyzerV1"},"type":"array"},"kind":{"const":"absent","type":"string"}},"required":["kind"],"type":"object"},{"description":"Authorization to inspect analyzer state was denied.","properties":{"kind":{"const":"denied","type":"string"}},"required":["kind"],"type":"object"},{"description":"Analyzer state could not be determined.","properties":{"kind":{"const":"unknown","type":"string"}},"required":["kind"],"type":"object"}]},
  LanguageServerStateV1: {"description":"Aggregate state of the project-active language-server analyzers.","oneOf":[{"const":"ready","description":"Every active analyzer is ready.","type":"string"},{"const":"available","description":"At least one analyzer is installed but has not produced a ready snapshot.","type":"string"},{"const":"refreshing","description":"At least one analyzer is currently refreshing/indexing.","type":"string"},{"const":"disabled","description":"At least one project analyzer is disabled.","type":"string"},{"const":"unavailable","description":"At least one project analyzer executable is unavailable.","type":"string"},{"const":"crashed","description":"At least one analyzer process crashed.","type":"string"}]},
