  NativeIntegrationGenerationBindingV1: {"additionalProperties":false,"description":"One immutable code-generation binding used by native integration analysis.","properties":{"content_identity":{"$ref":"#/$defs/ContentDigest"},"generation_id":{"$ref":"#/$defs/CodeGenerationId"},"project_id":{"$ref":"#/$defs/ProjectId"},"reference":{"anyOf":[{"$ref":"#/$defs/RefId"},{"type":"null"}]},"repository_id":{"$ref":"#/$defs/RepositoryId"},"seal_digest":{"$ref":"#/$defs/ManifestDigest"},"snapshot_digest":{"$ref":"#/$defs/ManifestDigest"},"source_revision":{"anyOf":[{"$ref":"#/$defs/GitOidV1"},{"type":"null"}]},"source_tree":{"$ref":"#/$defs/GitOidV1"},"worktree_id":{"anyOf":[{"$ref":"#/$defs/WorktreeId"},{"type":"null"}]}},"required":["generation_id","project_id","repository_id","snapshot_digest","content_identity","source_tree","seal_digest"],"type":"object"},
