  NativeIntegrationPreviewDispositionV1: {"description":"Truthful preview classification. Only `MechanicalIntegrationEligible`\ncarries apply-eligible evidence.","oneOf":[{"properties":{"detail":{"$ref":"#/$defs/MechanicalIntegrationModeV1"},"state":{"const":"mechanical_integration_eligible","type":"string"}},"required":["state","detail"],"type":"object"},{"properties":{"state":{"const":"already_integrated","type":"string"}},"required":["state"],"type":"object"},{"properties":{"detail":{"properties":{"conflict_digest":{"$ref":"#/$defs/ManifestDigest"}},"required":["conflict_digest"],"type":"object"},"state":{"const":"native_conflict","type":"string"}},"required":["state","detail"],"type":"object"},{"properties":{"detail":{"properties":{"evidence_digest":{"$ref":"#/$defs/ManifestDigest"}},"required":["evidence_digest"],"type":"object"},"state":{"const":"semantic_review_required","type":"string"}},"required":["state","detail"],"type":"object"},{"properties":{"detail":{"properties":{"reason":{"$ref":"#/$defs/NativeIntegrationUnavailabilityV1"}},"required":["reason"],"type":"object"},"state":{"const":"partial","type":"string"}},"required":["state","detail"],"type":"object"},{"properties":{"detail":{"properties":{"reason":{"$ref":"#/$defs/NativeIntegrationUnavailabilityV1"}},"required":["reason"],"type":"object"},"state":{"const":"unavailable","type":"string"}},"required":["state","detail"],"type":"object"}]},
