  NativeIntegrationSealedStackSnapshotV1: {"additionalProperties":false,"description":"Canonical stack-snapshot proof returned by `stack_snapshot` and consumed\nverbatim by preflight.","properties":{"authorized_scope_set_digest":{"$ref":"#/$defs/ManifestDigest"},"authorized_scope_set_id":{"$ref":"#/$defs/ScopeSetId"},"authorized_scope_set_revision":{"$ref":"#/$defs/ScopeSetRevision"},"destination":{"$ref":"#/$defs/ResolvedScope"},"grant_digest":{"$ref":"#/$defs/ManifestDigest"},"inventory_epoch":{"$ref":"#/$defs/WorktreeInventoryEpoch"},"inventory_snapshot_id":{"$ref":"#/$defs/WorktreeInventorySnapshotId"},"policy_digest":{"$ref":"#/$defs/ManifestDigest"},"selection":{"$ref":"#/$defs/NativeIntegrationSelectionBindingV1"},"source":{"$ref":"#/$defs/ResolvedScope"}},"required":["source","destination","authorized_scope_set_id","authorized_scope_set_revision","authorized_scope_set_digest","inventory_snapshot_id","inventory_epoch","selection","grant_digest","policy_digest"],"type":"object"},
  NativeIntegrationSelectionBindingV1: {"description":"Canonically sealed selection passed to the topology authority.\n\n`stack_snapshot` requests carry declaration content; its boundary seals\nthat declaration into this proof, and preflight accepts the proof verbatim.\nThe topology authority never discovers roots or edges.","oneOf":[{"properties":{"binding":{"properties":{"declared_revision":{"$ref":"#/$defs/BranchStackRevisionV1"},"destination_node_id":{"$ref":"#/$defs/StackNodeId"},"direction":{"$ref":"#/$defs/NativeIntegrationDirectionV1"},"revision_digest":{"$ref":"#/$defs/ManifestDigest"},"revision_id":{"$ref":"#/$defs/BranchStackRevisionId"},"source_node_id":{"$ref":"#/$defs/StackNodeId"},"stack_id":{"$ref":"#/$defs/BranchStackId"}},"required":["stack_id","revision_id","revision_digest","declared_revision","source_node_id","destination_node_id","direction"],"type":"object"},"kind":{"const":"declared_stack_edge","type":"string"}},"required":["kind","binding"],"type":"object"},{"properties":{"binding":{"properties":{"destination_ref":{"$ref":"#/$defs/RefId"},"proposal_digest":{"$ref":"#/$defs/ManifestDigest"},"source_ref":{"$ref":"#/$defs/RefId"}},"required":["proposal_digest","source_ref","destination_ref"],"type":"object"},"kind":{"const":"independent_branch","type":"string"}},"required":["kind","binding"],"type":"object"}]},
  NativeIntegrationSelectionDeclarationV1: {"description":"Explicit caller declaration for one native-integration selection.\n\nDeclared stacks contain the visible nodes and edges, while the daemon\nderives canonical order and the revision digest through the domain\nconstructor. Callers cannot submit either derived field.","oneOf":[{"additionalProperties":false,"properties":{"binding":{"additionalProperties":false,"properties":{"destination_node_id":{"$ref":"#/$defs/StackNodeId"},"direction":{"$ref":"#/$defs/NativeIntegrationDirectionV1"},"edges":{"items":{"$ref":"#/$defs/BranchStackEdgeV1"},"type":"array"},"nodes":{"items":{"$ref":"#/$defs/BranchStackNodeV1"},"type":"array"},"revision_id":{"$ref":"#/$defs/BranchStackRevisionId"},"source_node_id":{"$ref":"#/$defs/StackNodeId"},"stack_id":{"$ref":"#/$defs/BranchStackId"}},"required":["stack_id","revision_id","nodes","edges","source_node_id","destination_node_id","direction"],"type":"object"},"kind":{"const":"declared_stack_edge","type":"string"}},"required":["kind","binding"],"type":"object"},{"additionalProperties":false,"properties":{"binding":{"additionalProperties":false,"properties":{"destination_ref":{"$ref":"#/$defs/RefId"},"proposal_digest":{"$ref":"#/$defs/ManifestDigest"},"source_ref":{"$ref":"#/$defs/RefId"}},"required":["proposal_digest","source_ref","destination_ref"],"type":"object"},"kind":{"const":"independent_branch","type":"string"}},"required":["kind","binding"],"type":"object"}]},
