  NativeIntegrationSemanticConflictV1: {"additionalProperties":false,"description":"One deterministic conflict finding with source evidence from both branches.","properties":{"destination":{"$ref":"#/$defs/NativeIntegrationAnalysisAnchorV1"},"evidence_digest":{"$ref":"#/$defs/ManifestDigest"},"kind":{"$ref":"#/$defs/NativeIntegrationSemanticConflictKindV1"},"source":{"$ref":"#/$defs/NativeIntegrationAnalysisAnchorV1"}},"required":["kind","source","destination","evidence_digest"],"type":"object"},
  NativeIntegrationSnapshotProjectionV1: {"additionalProperties":false,"description":"Bounded projection of one frozen selection.","properties":{"destination_ref":{"$ref":"#/$defs/RefId"},"frozen_at":{"$ref":"#/$defs/UtcMicros"},"inventory_epoch":{"$ref":"#/$defs/WorktreeInventoryEpoch"},"project_id":{"$ref":"#/$defs/ProjectId"},"repository_id":{"$ref":"#/$defs/RepositoryId"},"selection_digest":{"$ref":"#/$defs/ManifestDigest"},"source_ref":{"$ref":"#/$defs/RefId"}},"required":["selection_digest","project_id","repository_id","source_ref","destination_ref","inventory_epoch","frozen_at"],"type":"object"},
  NativeIntegrationStatusProjectionV1: {"additionalProperties":false,"description":"Bounded projection of one durable transaction status.","properties":{"cancellation_requested":{"type":"boolean"},"destination_ref":{"$ref":"#/$defs/RefId"},"phase":{"$ref":"#/$defs/NativeIntegrationPhaseV1"},"phase_revision":{"format":"uint64","minimum":0,"type":"integer"},"preview_digest":{"$ref":"#/$defs/ManifestDigest"},"preview_id":{"$ref":"#/$defs/NativeIntegrationPreviewId"},"repository_id":{"$ref":"#/$defs/RepositoryId"},"terminal_outcome":{"anyOf":[{"$ref":"#/$defs/NativeIntegrationTerminalOutcomeV1"},{"type":"null"}]},"transaction_id":{"$ref":"#/$defs/NativeIntegrationTransactionId"},"updated_at":{"$ref":"#/$defs/UtcMicros"}},"required":["transaction_id","preview_id","preview_digest","repository_id","destination_ref","phase","phase_revision","cancellation_requested","updated_at"],"type":"object"},
  NativeIntegrationSurfaceUnavailableV1: {"description":"Why a native-integration operation produced no advancing state.\n\nEvery variant is read-only and truthful. None of them authorizes apply, and\na denied or absent target is reported indistinguishably from an unavailable\nauthority so no identity, path, count, or topology leaks.","oneOf":[{"enum":["partial","stale","denied","reset_required","durability_uncertain","cancelled","approval_conflict","transaction_conflict","recovery_required","needs_inspection","unknown_transaction"],"type":"string"},{"const":"authority_unmounted","description":"No native-integration runtime authority is mounted for this daemon.","type":"string"}]},
