  NodeDetailsV1: {"additionalProperties":false,"properties":{"branches":{"description":"Exact counters; `None`, and listed in `unavailable_fields`, when\n`complexity_analysis` reports the bounded walk did not cover the body.","format":"uint32","minimum":0,"type":["integer","null"]},"complexity_analysis":{"$ref":"#/$defs/ComplexityAnalysisV1"},"cost_to_expand":{"$ref":"#/$defs/NodeExpansionCostV1"},"cyclomatic_complexity":{"format":"uint32","minimum":0,"type":["integer","null"]},"derives":{"items":{"type":"string"},"type":"array"},"docstring":{"type":["string","null"]},"end_line":{"format":"uint32","minimum":0,"type":"integer"},"file":{"type":"string"},"freshness":{"anyOf":[{"$ref":"#/$defs/PrimitiveSearchFreshnessV1"},{"type":"null"}],"description":"The worktree verdict a served graph read opens with."},"id":{"type":"string"},"is_async":{"type":"boolean"},"kind":{"type":"string"},"loops":{"format":"uint32","minimum":0,"type":["integer","null"]},"max_nesting":{"format":"uint32","minimum":0,"type":["integer","null"]},"name":{"type":"string"},"qualified_name":{"type":"string"},"signature":{"type":["string","null"]},"start_line":{"format":"uint32","minimum":0,"type":"integer"},"unavailable_fields":{"items":{"type":"string"},"type":"array"},"visibility":{"type":"string"}},"required":["id","name","kind","qualified_name","file","start_line","end_line","is_async","derives","visibility","complexity_analysis","cost_to_expand","unavailable_fields"],"type":"object"},
