  RetrievedPageV1: {"additionalProperties":false,"description":"One page of the stored response, sized so its response frame fits the\nresponse budget.","properties":{"content":{"type":"string"},"created_at":{"format":"int64","type":"integer"},"expired":{"description":"Always `false`: a page is only served from a live record.","type":"boolean"},"expires_at":{"format":"int64","type":"integer"},"freshness":{"anyOf":[{"$ref":"#/$defs/PrimitiveSearchFreshnessV1"},{"type":"null"}],"description":"The worktree verdict a served graph read opens with."},"handle":{"type":"string"},"has_more":{"type":"boolean"},"next_offset":{"description":"Where the next page starts; absent on the last page.","format":"uint64","minimum":0,"type":["integer","null"]},"offset":{"format":"uint64","minimum":0,"type":"integer"},"original_chars":{"format":"uint64","minimum":0,"type":"integer"},"total_chars":{"format":"uint64","minimum":0,"type":"integer"}},"required":["handle","expired","original_chars","total_chars","offset","has_more","created_at","expires_at","content"],"type":"object"},
