  RuntimeDoctorReportV1: {"description":"The daemon's canonical Doctor report as this route could read it.","oneOf":[{"additionalProperties":false,"properties":{"kind":{"const":"observed","type":"string"},"language_servers":{"$ref":"#/$defs/LanguageServerReadV1"},"report":{"$ref":"#/$defs/DoctorReportV1"},"schema_convergences":{"items":{"$ref":"#/$defs/SchemaConvergenceFindingV1"},"type":"array"},"table_growth_evidence":{"items":{"$ref":"#/$defs/TableGrowthDoctorEvidenceV1"},"type":"array"}},"required":["kind","report","table_growth_evidence","schema_convergences","language_servers"],"type":"object"},{"additionalProperties":false,"description":"The reader is mounted and the read failed.","properties":{"kind":{"const":"unknown","type":"string"},"language_servers":{"$ref":"#/$defs/LanguageServerReadV1"},"schema_convergences":{"items":{"$ref":"#/$defs/SchemaConvergenceFindingV1"},"type":"array"},"table_growth_evidence":{"items":{"$ref":"#/$defs/TableGrowthDoctorEvidenceV1"},"type":"array"}},"required":["kind","table_growth_evidence","schema_convergences","language_servers"],"type":"object"},{"additionalProperties":false,"description":"No Doctor reader is mounted on this route.","properties":{"kind":{"const":"unsupported","type":"string"},"language_servers":{"$ref":"#/$defs/LanguageServerReadV1"},"schema_convergences":{"items":{"$ref":"#/$defs/SchemaConvergenceFindingV1"},"type":"array"},"table_growth_evidence":{"items":{"$ref":"#/$defs/TableGrowthDoctorEvidenceV1"},"type":"array"}},"required":["kind","table_growth_evidence","schema_convergences","language_servers"],"type":"object"}]},
