  ScopeOutcomeForArrayOfAnyValue: {"description":"Truthful outcome for one authorized root or an aggregate over roots.\n\n`Denied` and `Unavailable` carry no value and therefore cannot be confused\nwith a successful empty result.","oneOf":[{"properties":{"outcome":{"const":"exact","type":"string"},"value":{"items":true,"type":"array"}},"required":["outcome","value"],"type":"object"},{"properties":{"outcome":{"const":"partial","type":"string"},"value":{"properties":{"reason":{"$ref":"#/$defs/ScopePartialReasonV1"},"value":{"items":true,"type":"array"}},"required":["value","reason"],"type":"object"}},"required":["outcome","value"],"type":"object"},{"properties":{"outcome":{"const":"denied","type":"string"}},"required":["outcome"],"type":"object"},{"properties":{"outcome":{"const":"unavailable","type":"string"},"value":{"properties":{"reason":{"$ref":"#/$defs/ScopeUnavailableReasonV1"}},"required":["reason"],"type":"object"}},"required":["outcome","value"],"type":"object"}]},
  ScopeOutcomeForNullableRootGenerationV1: {"description":"Truthful outcome for one authorized root or an aggregate over roots.\n\n`Denied` and `Unavailable` carry no value and therefore cannot be confused\nwith a successful empty result.","oneOf":[{"properties":{"outcome":{"const":"exact","type":"string"},"value":{"anyOf":[{"$ref":"#/$defs/RootGenerationV1"},{"type":"null"}]}},"required":["outcome","value"],"type":"object"},{"properties":{"outcome":{"const":"partial","type":"string"},"value":{"properties":{"reason":{"$ref":"#/$defs/ScopePartialReasonV1"},"value":{"anyOf":[{"$ref":"#/$defs/RootGenerationV1"},{"type":"null"}]}},"required":["reason"],"type":"object"}},"required":["outcome","value"],"type":"object"},{"properties":{"outcome":{"const":"denied","type":"string"}},"required":["outcome"],"type":"object"},{"properties":{"outcome":{"const":"unavailable","type":"string"},"value":{"properties":{"reason":{"$ref":"#/$defs/ScopeUnavailableReasonV1"}},"required":["reason"],"type":"object"}},"required":["outcome","value"],"type":"object"}]},
  ScopeOutcomeForNullableString: {"description":"Truthful outcome for one authorized root or an aggregate over roots.\n\n`Denied` and `Unavailable` carry no value and therefore cannot be confused\nwith a successful empty result.","oneOf":[{"properties":{"outcome":{"const":"exact","type":"string"},"value":{"type":["string","null"]}},"required":["outcome","value"],"type":"object"},{"properties":{"outcome":{"const":"partial","type":"string"},"value":{"properties":{"reason":{"$ref":"#/$defs/ScopePartialReasonV1"},"value":{"type":["string","null"]}},"required":["reason"],"type":"object"}},"required":["outcome","value"],"type":"object"},{"properties":{"outcome":{"const":"denied","type":"string"}},"required":["outcome"],"type":"object"},{"properties":{"outcome":{"const":"unavailable","type":"string"},"value":{"properties":{"reason":{"$ref":"#/$defs/ScopeUnavailableReasonV1"}},"required":["reason"],"type":"object"}},"required":["outcome","value"],"type":"object"}]},
