  ScopeSourceBinding: {"additionalProperties":false,"description":"A source-to-authority binding. It stores only the source kind, a redacted\nlocator digest, and the pre-resolved authority reference.","properties":{"authority":{"$ref":"#/$defs/AuthorityRef"},"binding_id":{"$ref":"#/$defs/SourceBindingId"},"source_kind":{"$ref":"#/$defs/SourceKindV1"},"source_locator_digest":{"$ref":"#/$defs/LocatorDigest"}},"required":["binding_id","source_kind","source_locator_digest","authority"],"type":"object"},
