  ScoreDomainId: {"description":"Strongly typed canonical identity: `ScoreDomainId`.","type":"string"},
  SearchCompleteV1: {"additionalProperties":false,"properties":{"code_generation":{"type":"string"},"coverage":{"$ref":"#/$defs/SearchCoverageV1"},"external_import_hint":{"anyOf":[{"$ref":"#/$defs/SearchExternalImportHintV1"},{"type":"null"}]},"freshness":{"$ref":"#/$defs/PrimitiveSearchFreshnessV1","description":"Freshness of the served code generation, derived from the typed lane\ncoverage and the daemon scheduler's worktree state."},"lexical_anchors":{"description":"Outcome of every caller `lexical_anchors` entry, beside the routes.","items":{"$ref":"#/$defs/ContextLexicalAnchorV1"},"type":["array","null"]},"lexical_routes":{"description":"Every lexical route fused into this page; present only when a route\nbeyond the strict query ran or ranked a result.","items":{"$ref":"#/$defs/SearchLexicalRouteV1"},"type":["array","null"]},"next_cursor":{"description":"Authenticated continuation for the next page; null on the last page.","type":["string","null"]},"query_fallback_digest":{"type":"string"},"query_route":{"anyOf":[{"$ref":"#/$defs/SearchQueryRouteV1"},{"type":"null"}],"description":"Which lane the query's shape selected, and its margin."},"results":{"items":{"$ref":"#/$defs/SearchResultRowV1"},"type":"array"},"scope_prefix":{"description":"The session's scope prefix. Ranked candidates carry no file path, so\nthe scope is reported and not applied.","type":["string","null"]},"scope_prefix_applied":{"type":["boolean","null"]},"verified_graph_evidence":{"anyOf":[{"$ref":"#/$defs/PrimitiveUnavailableEvidenceV1"},{"type":"null"}]}},"required":["freshness","code_generation","query_fallback_digest","coverage","results"],"type":"object"},
  SearchCoverageV1: {"additionalProperties":false,"description":"Per-lane recall of one search, so a full-recall answer is told apart from\none produced while a lane was down.","properties":{"exact":{"$ref":"#/$defs/SearchLaneStatusV1"},"graph":{"$ref":"#/$defs/SearchLaneStatusV1"},"lexical":{"$ref":"#/$defs/SearchLaneStatusV1"},"recall":{"$ref":"#/$defs/PrimitiveRecallV1"}},"required":["exact","lexical","graph","recall"],"type":"object"},
