  SearchLaneStateV1: {"description":"A lane that did not serve the current complete generation. A partial\nlane names its generation and reason when it has them, null otherwise.","oneOf":[{"additionalProperties":false,"properties":{"generation":{"type":"string"},"status":{"const":"stale","type":"string"}},"required":["status","generation"],"type":"object"},{"additionalProperties":false,"properties":{"generation":{"type":["string","null"]},"reason":{"type":["string","null"]},"status":{"const":"partial","type":"string"}},"required":["status"],"type":"object"},{"additionalProperties":false,"properties":{"reason":{"type":"string"},"status":{"const":"unavailable","type":"string"}},"required":["status","reason"],"type":"object"}]},
