  SearchLexicalProximityV1: {"additionalProperties":false,"description":"Ordered terms that must occur in one field within `maximum_gap`\nintervening tokens of each other.","properties":{"maximum_gap":{"format":"uint32","maximum":8,"minimum":0,"type":"integer"},"terms":{"items":{"type":"string"},"maxItems":8,"minItems":2,"type":"array"}},"required":["terms","maximum_gap"],"type":"object"},
  SearchLexicalRouteV1: {"description":"One lexical route fused into the page, with its display label.","oneOf":[{"additionalProperties":false,"description":"The caller's strict lexical query.","properties":{"label":{"type":"string"},"route":{"const":"query","type":"string"}},"required":["route","label"],"type":"object"},{"additionalProperties":false,"description":"One caller-supplied exact identifier or term.","properties":{"anchor":{"type":"string"},"label":{"type":"string"},"route":{"const":"anchor","type":"string"}},"required":["route","anchor","label"],"type":"object"},{"additionalProperties":false,"description":"Identifier-shaped tokens of the query, restricted to symbol names.","properties":{"label":{"type":"string"},"route":{"const":"preferred_symbol","type":"string"},"tokens":{"items":{"type":"string"},"type":"array"}},"required":["route","tokens","label"],"type":"object"},{"additionalProperties":false,"description":"Identifier and path components recovered from the strict query.","properties":{"label":{"type":"string"},"route":{"const":"identifier_split","type":"string"},"strict_query":{"type":"string"},"terms":{"items":{"type":"string"},"type":"array"}},"required":["route","strict_query","terms","label"],"type":"object"},{"additionalProperties":false,"description":"A configured query-time vocabulary alternative.","properties":{"alternative":{"type":"string"},"label":{"type":"string"},"reason":{"$ref":"#/$defs/SearchLexicalAlternativeReasonV1"},"route":{"const":"alias","type":"string"},"strict_query":{"type":"string"}},"required":["route","strict_query","alternative","reason","label"],"type":"object"}]},
