  SearchQueryRouteV1: {"additionalProperties":false,"description":"The query-shape routing decision behind a page.","properties":{"decided_by":{"$ref":"#/$defs/SearchQueryRouteDeciderV1"},"margin":{"description":"Distance from the name gate in [-0.5, 0.5]: the share of the query's\ncontent words that are identifier-shaped, minus one half. The gate\nselects `name` at or above 0. Reported when the caller decided too.\nIt describes query shape only and is not an answerability signal.","format":"double","type":"number"},"route":{"$ref":"#/$defs/SearchQueryRouteKindV1"}},"required":["route","margin","decided_by"],"type":"object"},
  SearchResultDisplayV1: {"additionalProperties":false,"properties":{"kind":{"type":"string"},"name":{"type":"string"},"path":{"type":"string"},"qualified_name":{"type":"string"}},"required":["name","qualified_name","kind","path"],"type":"object"},
  SearchResultRowV1: {"additionalProperties":false,"description":"One ranked candidate with its generation-bound display metadata.","properties":{"candidate":{"$ref":"#/$defs/FusedCandidate"},"display":{"anyOf":[{"$ref":"#/$defs/SearchResultDisplayV1"},{"type":"null"}]},"display_unavailable":{"anyOf":[{"$ref":"#/$defs/SearchDisplayUnavailableV1"},{"type":"null"}],"description":"Why `display` is absent from this ranked candidate."},"final_ordinal":{"format":"uint32","minimum":0,"type":"integer"},"lexical_routes":{"description":"The lexical routes that ranked this candidate.","items":{"$ref":"#/$defs/SearchRouteMatchV1"},"type":["array","null"]},"node_id":{"description":"The graph symbol to read with `tracedecay_source_body`.","type":["string","null"]}},"required":["candidate","final_ordinal"],"type":"object"},
  SearchRouteMatchV1: {"additionalProperties":false,"description":"One route that ranked a candidate, named by its route label.","properties":{"matched_terms":{"items":{"type":"string"},"type":"array"},"route":{"type":"string"},"score_micros":{"format":"uint64","minimum":0,"type":"integer"},"spelling_variants":{"items":{"$ref":"#/$defs/SearchSpellingVariantV1"},"type":"array"}},"required":["route","score_micros","matched_terms"],"type":"object"},
