  SkillUsageRecord: {"description":"One skill's durable usage counters. The ledger stores one per skill; a\nsummary is the same record merged with the skill's current metadata.","properties":{"activated_at":{"description":"When the skill last transitioned into the active state; mirrors the\nmanaged skill metadata so outcome scoring works from summaries alone.","format":"int64","type":["integer","null"]},"category":{"type":["string","null"]},"created_by":{"type":["string","null"]},"first_seen_at":{"format":"int64","type":"integer"},"imported_analytics_events":{"description":"Import keys that already counted toward this skill. They are not a\nstore-wide set: each key names this skill, so another skill must not\nshare the write.","items":{"type":"string"},"type":"array","uniqueItems":true},"last_activity_at":{"format":"int64","type":"integer"},"last_patched_at":{"format":"int64","type":["integer","null"]},"last_used_at":{"format":"int64","type":["integer","null"]},"last_viewed_at":{"format":"int64","type":["integer","null"]},"patch_count":{"format":"uint64","minimum":0,"type":"integer"},"pinned":{"type":"boolean"},"provenance_source":{"anyOf":[{"$ref":"#/$defs/ManagedSkillSource"},{"type":"null"}]},"schema_version":{"format":"uint32","minimum":0,"type":"integer"},"skill_id":{"type":"string"},"state":{"anyOf":[{"$ref":"#/$defs/ManagedSkillState"},{"type":"null"}]},"targets":{"default":[],"items":{"type":"string"},"type":"array"},"title":{"type":["string","null"]},"use_count":{"format":"uint64","minimum":0,"type":"integer"},"use_count_at_activation":{"format":"uint64","minimum":0,"type":["integer","null"]},"view_count":{"format":"uint64","minimum":0,"type":"integer"},"view_count_at_activation":{"description":"View/use totals captured at activation time so activity since activation\nis an exact delta rather than a heuristic.","format":"uint64","minimum":0,"type":["integer","null"]}},"required":["schema_version","skill_id","pinned","view_count","use_count","patch_count","first_seen_at","last_activity_at"],"type":"object"},
