  SourceEditDurableEffectPayloadV1: {"additionalProperties":false,"description":"Body-free source-edit evidence retained inside durable effect receipts.\n\nThis payload intentionally contains no caller-supplied edit text, preview\ndiff, moved span, import, diagnostic, or impact detail. It is also the\nexact replay outcome, so replay never fabricates a live edit body.","properties":{"before":{"type":["boolean","null"]},"cancelled":{"type":"boolean"},"change_count":{"format":"uint","minimum":0,"type":["integer","null"]},"durable_metadata_only":{"type":"boolean"},"effect_unknown":{"type":"boolean"},"failed":{"type":"boolean"},"files":{"items":{"type":"string"},"type":"array"},"finding_count":{"format":"uint","minimum":0,"type":["integer","null"]},"import_count":{"format":"uint","minimum":0,"type":["integer","null"]},"line":{"format":"uint32","minimum":0,"type":["integer","null"]},"message":{"type":"string"},"operation":{"$ref":"#/$defs/UseCaseId"},"reconciled":{"type":"boolean"},"success":{"type":"boolean"},"timed_out":{"type":"boolean"}},"required":["operation","success","files","failed","cancelled","timed_out","effect_unknown","reconciled","durable_metadata_only","message"],"type":"object"},
