  SourceFreshness: {"additionalProperties":false,"description":"Source freshness is source- and retriever-specific: there is no global\nage-decay multiplier. Missing, stale, incompatible, and current are\ndistinct states.","properties":{"compatibility":{"$ref":"#/$defs/FreshnessCompatibilityV1"},"generation_lag":{"format":"uint64","minimum":0,"type":["integer","null"]},"observed_at":{"$ref":"#/$defs/UtcMicros"},"policy_revision":{"$ref":"#/$defs/ComponentRevision"},"projection_watermark":{"format":"uint64","minimum":0,"type":["integer","null"]},"source_generation":{"format":"uint64","minimum":0,"type":["integer","null"]},"source_instance":{"$ref":"#/$defs/SourceInstanceKey"},"source_namespace":{"$ref":"#/$defs/SourceNamespace"},"source_watermark":{"format":"uint64","minimum":0,"type":["integer","null"]}},"required":["source_namespace","source_instance","observed_at","compatibility","policy_revision"],"type":"object"},
