  StatusCodeIndexFreshnessV1: {"description":"The code-index freshness of the served worktree, labeled the way readiness\nwaits report their last state.","oneOf":[{"additionalProperties":false,"properties":{"status":{"const":"current","type":"string"},"worktree":{"$ref":"#/$defs/CodeIndexWorktreeFreshnessV1"}},"required":["status","worktree"],"type":"object"},{"additionalProperties":false,"properties":{"status":{"const":"stale","type":"string"},"worktree":{"$ref":"#/$defs/CodeIndexWorktreeFreshnessV1"}},"required":["status","worktree"],"type":"object"},{"additionalProperties":false,"properties":{"status":{"const":"restoring","type":"string"},"worktree":{"$ref":"#/$defs/CodeIndexWorktreeFreshnessV1"}},"required":["status","worktree"],"type":"object"},{"additionalProperties":false,"properties":{"status":{"const":"warming","type":"string"},"worktree":{"$ref":"#/$defs/CodeIndexWorktreeFreshnessV1"}},"required":["status","worktree"],"type":"object"},{"additionalProperties":false,"properties":{"status":{"const":"parked","type":"string"},"worktree":{"$ref":"#/$defs/CodeIndexWorktreeFreshnessV1"}},"required":["status","worktree"],"type":"object"},{"additionalProperties":false,"description":"The last code-index mount failed; explicit reconciliation can retry it.","properties":{"message":{"type":"string"},"remediation":{"type":"string"},"status":{"const":"mount_failed","type":"string"}},"required":["status","message","remediation"],"type":"object"},{"additionalProperties":false,"properties":{"reason":{"type":"string"},"status":{"const":"unavailable","type":"string"}},"required":["status","reason"],"type":"object"}]},
  StatusGitStalenessUnavailableV1: {"oneOf":[{"const":"no_sealed_generation","description":"No complete generation has sealed for the worktree yet.","type":"string"},{"const":"sealed_generation_has_no_commit","description":"The sealed generation captured no commit, as in an unborn repository.","type":"string"},{"const":"git_head_unreadable","description":"The worktree's checked-out commit could not be read.","type":"string"}]},
